insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c481593f-1832-4a79-a219-672c4f160332', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Origins and Stakes of Classical Social Theory', 'This opening unit explains why classical social theory still matters. Students learn to read theory as a set of tools for naming social forces, not as museum pieces from the past.', 0),
  ('2415483b-be27-438d-b125-5daa5e844c02', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c481593f-1832-4a79-a219-672c4f160332', 'subtopic'::public.curated_course_node_type, 'What Makes Theory Classical', 'Students learn why certain texts become canonical and how canons are made, contested, expanded, and used.', 0),
  ('d1a77c7b-0559-453f-8af8-39c4ee74e22c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2415483b-be27-438d-b125-5daa5e844c02', 'concept'::public.curated_course_node_type, 'Foundational questions and durable concepts', null, 0),
  ('9b8fb52b-4398-43cc-a531-7e6d238c222e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2415483b-be27-438d-b125-5daa5e844c02', 'concept'::public.curated_course_node_type, 'Original texts versus later interpretation', null, 1),
  ('6a6cccc8-e323-41fe-8e73-00fc5f805a2f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2415483b-be27-438d-b125-5daa5e844c02', 'concept'::public.curated_course_node_type, 'Canon formation and exclusion', null, 2),
  ('d8dcefaa-8965-489a-a894-6db4516151b3', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2415483b-be27-438d-b125-5daa5e844c02', 'concept'::public.curated_course_node_type, 'Classical theory as a living vocabulary', null, 3),
  ('703aa0c6-9eac-46be-b6a9-5f46c3cc285a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c481593f-1832-4a79-a219-672c4f160332', 'subtopic'::public.curated_course_node_type, 'The Sociological Imagination', 'The point is to connect personal experience to historical and institutional conditions.', 1),
  ('1746d5cd-3c47-4b5c-abc7-807a52f07010', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '703aa0c6-9eac-46be-b6a9-5f46c3cc285a', 'concept'::public.curated_course_node_type, 'Private troubles and public issues', null, 0),
  ('3313791c-5781-4d44-a24a-6da818b7e633', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '703aa0c6-9eac-46be-b6a9-5f46c3cc285a', 'concept'::public.curated_course_node_type, 'Biography, history, and social structure', null, 1),
  ('10e2ad5b-1e4b-4c21-8cb0-753441bb8eff', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '703aa0c6-9eac-46be-b6a9-5f46c3cc285a', 'concept'::public.curated_course_node_type, 'Common sense versus sociological explanation', null, 2),
  ('01539922-01c3-4cc3-8532-ec076908ef68', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '703aa0c6-9eac-46be-b6a9-5f46c3cc285a', 'concept'::public.curated_course_node_type, 'Theory as disciplined distance from everyday assumptions', null, 3),
  ('caedd222-0a04-4530-a8c4-d9612e77a90f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c481593f-1832-4a79-a219-672c4f160332', 'subtopic'::public.curated_course_node_type, 'Order, Conflict, Meaning, and Change', 'Students learn the major questions that organize the whole course.', 2),
  ('96cdeb12-a034-466d-a6b7-3596586da9bd', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'caedd222-0a04-4530-a8c4-d9612e77a90f', 'concept'::public.curated_course_node_type, 'How social order is possible', null, 0),
  ('edbc5a69-3f33-4e2f-8d5f-3f07dc1172ff', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'caedd222-0a04-4530-a8c4-d9612e77a90f', 'concept'::public.curated_course_node_type, 'Why inequality persists', null, 1),
  ('90f5a812-c3c5-4392-9005-5b67447bd2ae', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'caedd222-0a04-4530-a8c4-d9612e77a90f', 'concept'::public.curated_course_node_type, 'How actors create meaning', null, 2),
  ('e48df145-2784-4459-ac6b-4e9b1bbc6ef9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'caedd222-0a04-4530-a8c4-d9612e77a90f', 'concept'::public.curated_course_node_type, 'How societies transform and break down', null, 3),
  ('5f9ef976-e147-405f-af74-da4f38e9d8a1', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Modernity, Revolution, Industrial Capitalism, and the Birth of Sociology', 'Classical theory emerged from upheaval. Students study the historical conditions that made society appear as something that could be analyzed, compared, governed, and changed.', 1),
  ('34d565a2-9814-4a01-8c98-ca975b07a3a7', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5f9ef976-e147-405f-af74-da4f38e9d8a1', 'subtopic'::public.curated_course_node_type, 'Enlightenment and Revolution', 'Students learn how reason, rights, secular authority, and democratic revolution reshaped theories of society.', 0),
  ('8ae546d4-fbca-4ee6-8420-a1b5ce61d02b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '34d565a2-9814-4a01-8c98-ca975b07a3a7', 'concept'::public.curated_course_node_type, 'Enlightenment reason and progress', null, 0),
  ('f1ff4456-9aac-48a0-b1fd-b33987620eab', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '34d565a2-9814-4a01-8c98-ca975b07a3a7', 'concept'::public.curated_course_node_type, 'French and American revolutions', null, 1),
  ('675736cb-75ea-428a-a2cb-5731454ec4bd', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '34d565a2-9814-4a01-8c98-ca975b07a3a7', 'concept'::public.curated_course_node_type, 'Citizenship and sovereignty', null, 2),
  ('c7813936-1c8d-4589-8d03-6389cd4123d4', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '34d565a2-9814-4a01-8c98-ca975b07a3a7', 'concept'::public.curated_course_node_type, 'The problem of social order after tradition', null, 3),
  ('a8ab0013-c22c-45e6-a0d0-579ff0b5479a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5f9ef976-e147-405f-af74-da4f38e9d8a1', 'subtopic'::public.curated_course_node_type, 'Industrial Capitalism', 'The gist is understanding how wage labor, factories, markets, and urban poverty forced new explanations of class and social change.', 1),
  ('56d6fb42-a3c4-45d5-80ca-85c54ed49524', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a8ab0013-c22c-45e6-a0d0-579ff0b5479a', 'concept'::public.curated_course_node_type, 'Industrialization and labor discipline', null, 0),
  ('21dad20e-20cb-4db3-883d-983f2de6271c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a8ab0013-c22c-45e6-a0d0-579ff0b5479a', 'concept'::public.curated_course_node_type, 'Capital accumulation and markets', null, 1),
  ('13e3ff70-733e-4e24-a630-cd2fae3bbb32', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a8ab0013-c22c-45e6-a0d0-579ff0b5479a', 'concept'::public.curated_course_node_type, 'Class formation', null, 2),
  ('7d6eeb41-e492-4fda-8f34-0c581ce7627a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a8ab0013-c22c-45e6-a0d0-579ff0b5479a', 'concept'::public.curated_course_node_type, 'Poverty, exploitation, and reform', null, 3),
  ('13ff82f7-9201-4187-a543-2414ddbb0f8d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5f9ef976-e147-405f-af74-da4f38e9d8a1', 'subtopic'::public.curated_course_node_type, 'Empire, Coloniality, and Global Modernity', 'Students learn that classical theory was produced inside a global order shaped by conquest, slavery, extraction, and racial hierarchy.', 2),
  ('0bc0363f-1a8d-4d33-b63c-27902690dbe9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '13ff82f7-9201-4187-a543-2414ddbb0f8d', 'concept'::public.curated_course_node_type, 'Colonial expansion', null, 0),
  ('7ff9440d-f8f8-46c6-924f-baf8f7d11dab', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '13ff82f7-9201-4187-a543-2414ddbb0f8d', 'concept'::public.curated_course_node_type, 'Slavery and abolition', null, 1),
  ('8a8ba34a-2ec2-4eee-b19f-87dbc8f71ace', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '13ff82f7-9201-4187-a543-2414ddbb0f8d', 'concept'::public.curated_course_node_type, 'Race science and empire', null, 2),
  ('725f1615-9561-4a0e-84b7-b0ddcc4ccf5c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '13ff82f7-9201-4187-a543-2414ddbb0f8d', 'concept'::public.curated_course_node_type, 'Global uneven development', null, 3),
  ('1e872f1c-3b05-4e1c-a868-7d8115283b5f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Auguste Comte, Positivism, and the Scientific Ambition of Sociology', 'Comte gives sociology one of its earliest self-descriptions as a science of society. Students learn both the ambition and the danger of trying to model social life after natural science.', 2),
  ('b6dab524-4110-43d7-a103-600a7691564d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '1e872f1c-3b05-4e1c-a868-7d8115283b5f', 'subtopic'::public.curated_course_node_type, 'Positivism', 'Students learn the appeal of empirical, law-seeking social science and the critiques it invites.', 0),
  ('15b4d1c9-11b7-4933-a775-6b58db234940', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b6dab524-4110-43d7-a103-600a7691564d', 'concept'::public.curated_course_node_type, 'Observation and classification', null, 0),
  ('f777841a-0f66-4b42-81cb-9958fec55e9c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b6dab524-4110-43d7-a103-600a7691564d', 'concept'::public.curated_course_node_type, 'Social laws and prediction', null, 1),
  ('fc189222-5524-414d-bbcd-62998cd1a79f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b6dab524-4110-43d7-a103-600a7691564d', 'concept'::public.curated_course_node_type, 'Hierarchy of the sciences', null, 2),
  ('5dc7b30b-3fe7-42ee-979d-8cff77f9a564', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b6dab524-4110-43d7-a103-600a7691564d', 'concept'::public.curated_course_node_type, 'Limits of positivist certainty', null, 3),
  ('91c3fde0-f3b4-4915-a474-94c2094f8305', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '1e872f1c-3b05-4e1c-a868-7d8115283b5f', 'subtopic'::public.curated_course_node_type, 'Social Statics and Social Dynamics', 'The point is to distinguish theories of order from theories of change.', 1),
  ('054d39f5-38e7-4b98-8aeb-f1e78bfc324c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '91c3fde0-f3b4-4915-a474-94c2094f8305', 'concept'::public.curated_course_node_type, 'Institutions and cohesion', null, 0);
