  ('a0fd96b4-46a2-4830-9185-831d8bc423e7', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '6bcaa226-5ad6-4c69-9dcd-a7e725c016ce', 'concept'::public.curated_course_node_type, 'Disciplinary naming and ambition', null, 0),
  ('e313e1ef-ac98-4f60-b6bf-ee608fb24b7e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '6bcaa226-5ad6-4c69-9dcd-a7e725c016ce', 'concept'::public.curated_course_node_type, 'Science, reform, and technocracy', null, 1),
  ('50f6782d-c927-4dd6-9b98-dff386e42085', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '6bcaa226-5ad6-4c69-9dcd-a7e725c016ce', 'concept'::public.curated_course_node_type, 'Gender and hierarchy in Comte''s thought', null, 2),
  ('e6b93c7f-be39-4f12-a1ef-27a2ad227c3f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '6bcaa226-5ad6-4c69-9dcd-a7e725c016ce', 'concept'::public.curated_course_node_type, 'Positivism in later sociology', null, 3),
  ('2c0a6d77-063a-486b-98b3-870058296941', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Karl Marx: Historical Materialism, Capitalism, Class, and Alienation', 'Marx offers a powerful theory of capitalism as a historical system organized by labor, exploitation, class struggle, and crisis. Students learn to connect economic relations to ideology, law, politics, and everyday life.', 3),
  ('2d9c8c28-34ac-499d-b06b-7e1ef72f18b7', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2c0a6d77-063a-486b-98b3-870058296941', 'subtopic'::public.curated_course_node_type, 'Historical Materialism', 'Students learn Marx''s method for explaining social change through production, class relations, and contradiction.', 0),
  ('46d78894-728e-45cd-ab4a-290daa624776', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2d9c8c28-34ac-499d-b06b-7e1ef72f18b7', 'concept'::public.curated_course_node_type, 'Forces and relations of production', null, 0),
  ('f9b14b79-c73b-4ec5-be49-0211ff226ee1', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2d9c8c28-34ac-499d-b06b-7e1ef72f18b7', 'concept'::public.curated_course_node_type, 'Base and superstructure debates', null, 1),
  ('ddf8ec52-80c4-42f1-9b03-670aced6ac06', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2d9c8c28-34ac-499d-b06b-7e1ef72f18b7', 'concept'::public.curated_course_node_type, 'Modes of production', null, 2),
  ('e54ba0ae-1255-46ea-89ab-1e1832237b89', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2d9c8c28-34ac-499d-b06b-7e1ef72f18b7', 'concept'::public.curated_course_node_type, 'Contradiction and historical change', null, 3),
  ('a482cd8b-864d-48ca-926f-36e6752a821c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2c0a6d77-063a-486b-98b3-870058296941', 'subtopic'::public.curated_course_node_type, 'Capitalism and Exploitation', 'The gist is understanding capitalism as a social relation, not just a market system.', 1),
  ('78b07b1f-88a0-4641-bae6-86c45cdd8c47', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a482cd8b-864d-48ca-926f-36e6752a821c', 'concept'::public.curated_course_node_type, 'Commodity and commodity fetishism', null, 0),
  ('a2eeee8b-0c5e-46a0-9c76-e4ce9a02fed4', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a482cd8b-864d-48ca-926f-36e6752a821c', 'concept'::public.curated_course_node_type, 'Surplus value and exploitation', null, 1),
  ('f1703427-2fa8-490e-a932-e90bef9e97d6', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a482cd8b-864d-48ca-926f-36e6752a821c', 'concept'::public.curated_course_node_type, 'Alienation and labor', null, 2),
  ('e3732704-5a50-4086-9aa1-b0004b86f1ac', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'a482cd8b-864d-48ca-926f-36e6752a821c', 'concept'::public.curated_course_node_type, 'Accumulation, crisis, and competition', null, 3),
  ('3c6d1876-a8b1-4d76-93bb-c4dadf2e8a75', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2c0a6d77-063a-486b-98b3-870058296941', 'subtopic'::public.curated_course_node_type, 'Class, Ideology, and Revolution', 'Students learn how Marx links material interests to political struggle and consciousness.', 2),
  ('2142ca17-deb4-4c19-b05c-42194ea4be5f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3c6d1876-a8b1-4d76-93bb-c4dadf2e8a75', 'concept'::public.curated_course_node_type, 'Bourgeoisie and proletariat', null, 0),
  ('1c4beaec-8ed9-4cf5-a19a-966447aea294', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3c6d1876-a8b1-4d76-93bb-c4dadf2e8a75', 'concept'::public.curated_course_node_type, 'Class in itself and for itself', null, 1),
  ('b3c189c7-10b7-4bee-8249-4f6ac4ce5e8c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3c6d1876-a8b1-4d76-93bb-c4dadf2e8a75', 'concept'::public.curated_course_node_type, 'Ideology and false consciousness', null, 2),
  ('23eb97d3-7946-4263-a6bd-a86b6118e757', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3c6d1876-a8b1-4d76-93bb-c4dadf2e8a75', 'concept'::public.curated_course_node_type, 'Revolution, reform, and critique', null, 3),
  ('9546232f-1192-48c1-abfd-36d16cdfe291', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Emile Durkheim: Social Facts, Solidarity, Anomie, and Suicide', 'Durkheim asks how societies hold together and what happens when moral regulation breaks down. Students learn the logic of social facts, solidarity, anomie, suicide, and ritual.', 4),
  ('20859779-6c62-4b78-b924-77ff7535c9dd', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '9546232f-1192-48c1-abfd-36d16cdfe291', 'subtopic'::public.curated_course_node_type, 'Social Facts and Method', 'Students learn Durkheim''s claim that social phenomena must be treated as realities external to individuals.', 0),
  ('a1e6315f-74c5-47c3-94be-24870de315ce', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '20859779-6c62-4b78-b924-77ff7535c9dd', 'concept'::public.curated_course_node_type, 'Externality and constraint', null, 0),
  ('8d39db41-8720-4dea-bc36-e6b90d420a92', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '20859779-6c62-4b78-b924-77ff7535c9dd', 'concept'::public.curated_course_node_type, 'Rules of sociological method', null, 1),
  ('bd8b3038-ba92-460d-9c8f-c486c57d111d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '20859779-6c62-4b78-b924-77ff7535c9dd', 'concept'::public.curated_course_node_type, 'Collective representations', null, 2),
  ('954e6094-aedf-4045-a31a-ea63c8c83585', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '20859779-6c62-4b78-b924-77ff7535c9dd', 'concept'::public.curated_course_node_type, 'Normal and pathological forms', null, 3),
  ('c9a5100d-9e97-4e09-b155-a7b8a2a11ba2', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '9546232f-1192-48c1-abfd-36d16cdfe291', 'subtopic'::public.curated_course_node_type, 'Solidarity and Division of Labor', 'The point is to compare cohesion in traditional and modern societies.', 1),
  ('198fe5dc-1530-47d3-9346-55ac8ab86286', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c9a5100d-9e97-4e09-b155-a7b8a2a11ba2', 'concept'::public.curated_course_node_type, 'Mechanical solidarity', null, 0),
  ('6be748b5-35e9-421f-aabd-bba13ed55e24', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c9a5100d-9e97-4e09-b155-a7b8a2a11ba2', 'concept'::public.curated_course_node_type, 'Organic solidarity', null, 1),
  ('c8457cf3-3821-4b91-96a8-284b7c276dee', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c9a5100d-9e97-4e09-b155-a7b8a2a11ba2', 'concept'::public.curated_course_node_type, 'Law as an index of solidarity', null, 2),
  ('1046807b-5322-4fee-a831-543951149c1e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'c9a5100d-9e97-4e09-b155-a7b8a2a11ba2', 'concept'::public.curated_course_node_type, 'Anomie and forced division of labor', null, 3),
  ('5437299e-741f-4ccd-b47e-f2fa1fce5ab3', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '9546232f-1192-48c1-abfd-36d16cdfe291', 'subtopic'::public.curated_course_node_type, 'Suicide, Religion, and Ritual', 'Students learn how Durkheim connects individual action to social integration and collective meaning.', 2),
  ('407d5b50-6dc6-45ab-95e3-fc70b82d94bc', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5437299e-741f-4ccd-b47e-f2fa1fce5ab3', 'concept'::public.curated_course_node_type, 'Egoistic, altruistic, anomic, and fatalistic suicide', null, 0),
  ('f138e63d-e377-4902-8435-0d4f7c2bd2c5', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5437299e-741f-4ccd-b47e-f2fa1fce5ab3', 'concept'::public.curated_course_node_type, 'Integration and regulation', null, 1),
  ('0f1ea616-55eb-437b-a9c7-230f54537c2f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5437299e-741f-4ccd-b47e-f2fa1fce5ab3', 'concept'::public.curated_course_node_type, 'Sacred and profane', null, 2),
  ('cf5bb3ba-fd54-4032-96d2-862d8f1fc584', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5437299e-741f-4ccd-b47e-f2fa1fce5ab3', 'concept'::public.curated_course_node_type, 'Ritual, classification, and collective effervescence', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('56abe1ed-beed-4529-8ace-13bedc556e84', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Max Weber: Interpretive Sociology, Rationalization, Authority, and Bureaucracy', 'Weber teaches students to analyze meaning, power, legitimacy, and rationalization. His work helps explain modern bureaucracy, authority, capitalism, religion, and the tension between values and facts.', 5),
  ('d5990417-2e12-4651-bc9a-622776c0e16d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '56abe1ed-beed-4529-8ace-13bedc556e84', 'subtopic'::public.curated_course_node_type, 'Interpretive Sociology', 'Students learn Weber''s method for understanding meaningful social action without reducing it to psychology.', 0),
  ('3fc6c34f-ae64-4066-b2bd-f86488b92809', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'd5990417-2e12-4651-bc9a-622776c0e16d', 'concept'::public.curated_course_node_type, 'Verstehen', null, 0),
  ('4fef0ebe-b56c-41d8-85be-5d9bc08a1d42', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'd5990417-2e12-4651-bc9a-622776c0e16d', 'concept'::public.curated_course_node_type, 'Types of social action', null, 1),
  ('f8ab74dc-9e3b-4c1a-83b6-fc63cbff2424', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'd5990417-2e12-4651-bc9a-622776c0e16d', 'concept'::public.curated_course_node_type, 'Ideal types', null, 2),
  ('61e3cbcd-1756-45fe-976d-6b511dbda9fd', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'd5990417-2e12-4651-bc9a-622776c0e16d', 'concept'::public.curated_course_node_type, 'Value relevance and objectivity', null, 3),
  ('e51faaf0-4a93-436f-bbad-93f2e8b8ef2b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '56abe1ed-beed-4529-8ace-13bedc556e84', 'subtopic'::public.curated_course_node_type, 'Rationalization and Disenchantment', 'The gist is learning Weber''s account of modern life as increasingly calculable, rule-bound, and disenchanted.', 1),
  ('df4ca1ba-731d-4bf0-9c91-1ffa88941ac7', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e51faaf0-4a93-436f-bbad-93f2e8b8ef2b', 'concept'::public.curated_course_node_type, 'Formal and substantive rationality', null, 0),
  ('6176b410-0b7b-4f51-a9e1-d22e56c96b03', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e51faaf0-4a93-436f-bbad-93f2e8b8ef2b', 'concept'::public.curated_course_node_type, 'The Protestant ethic thesis', null, 1),
  ('16884b17-cfcd-4b55-9d86-ec83862074b8', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e51faaf0-4a93-436f-bbad-93f2e8b8ef2b', 'concept'::public.curated_course_node_type, 'Disenchantment', null, 2),
  ('75120ea2-0687-4483-9c26-e6e8cc4a095a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e51faaf0-4a93-436f-bbad-93f2e8b8ef2b', 'concept'::public.curated_course_node_type, 'The iron cage', null, 3),
  ('41d80c5b-aebc-47d8-8eba-f6bb95fc34c9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '56abe1ed-beed-4529-8ace-13bedc556e84', 'subtopic'::public.curated_course_node_type, 'Authority, Bureaucracy, and Domination', 'Students learn how power becomes legitimate and how modern administration shapes social life.', 2),
  ('85ece242-3981-4c1c-bc36-2dd655d10396', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '41d80c5b-aebc-47d8-8eba-f6bb95fc34c9', 'concept'::public.curated_course_node_type, 'Traditional, charismatic, and legal-rational authority', null, 0),
  ('52a2b785-1ffc-41bc-8b4c-775b887f7b94', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '41d80c5b-aebc-47d8-8eba-f6bb95fc34c9', 'concept'::public.curated_course_node_type, 'Bureaucratic organization', null, 1),
  ('e74dc3bb-34f9-4ac1-a517-8e83b4b541e2', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '41d80c5b-aebc-47d8-8eba-f6bb95fc34c9', 'concept'::public.curated_course_node_type, 'Status groups and parties', null, 2),
  ('71ab5bcb-6a5b-4e01-894e-f19da18f8f36', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '41d80c5b-aebc-47d8-8eba-f6bb95fc34c9', 'concept'::public.curated_course_node_type, 'Politics, ethics, and responsibility', null, 3),
  ('14beafe7-6380-4b69-9708-46377d4e4b58', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Georg Simmel: Forms of Association, Money, Metropolis, and Strangerhood', 'Simmel helps students see social life in forms of interaction: exchange, conflict, secrecy, sociability, distance, and individuality. His work bridges micro encounters and macro modernity.', 6),
  ('28c9b4e4-0e0a-400f-b651-ea0fae72566a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '14beafe7-6380-4b69-9708-46377d4e4b58', 'subtopic'::public.curated_course_node_type, 'Forms of Association', 'Students learn to analyze recurring interaction patterns across different social contents.', 0),
  ('f82bc059-3a4a-4217-a2d6-3449853145e8', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '28c9b4e4-0e0a-400f-b651-ea0fae72566a', 'concept'::public.curated_course_node_type, 'Dyads and triads', null, 0),
  ('097d0332-54e4-498c-8bce-3be94dfa30ee', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '28c9b4e4-0e0a-400f-b651-ea0fae72566a', 'concept'::public.curated_course_node_type, 'Exchange and reciprocity', null, 1),
  ('d5951c1a-8bba-418b-a97b-ff3a86460189', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '28c9b4e4-0e0a-400f-b651-ea0fae72566a', 'concept'::public.curated_course_node_type, 'Conflict as social form', null, 2),
  ('e8db694f-a0b1-47f0-a321-83852b102f5a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '28c9b4e4-0e0a-400f-b651-ea0fae72566a', 'concept'::public.curated_course_node_type, 'Sociability, secrecy, and trust', null, 3),
  ('5c8e2c69-9301-4ff3-ae0b-a4910adc9293', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '14beafe7-6380-4b69-9708-46377d4e4b58', 'subtopic'::public.curated_course_node_type, 'Money and Modern Life', 'The point is to understand how money transforms value, individuality, relationships, and social distance.', 1),
  ('201b81f6-1d8b-4040-aecb-1a53cb21b345', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5c8e2c69-9301-4ff3-ae0b-a4910adc9293', 'concept'::public.curated_course_node_type, 'The philosophy of money', null, 0),
  ('74eb78e1-aaef-4ec1-ada2-aeec32275184', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5c8e2c69-9301-4ff3-ae0b-a4910adc9293', 'concept'::public.curated_course_node_type, 'Objective and subjective culture', null, 1),
  ('2a4708d5-508e-4e57-8869-f322bca46d5d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5c8e2c69-9301-4ff3-ae0b-a4910adc9293', 'concept'::public.curated_course_node_type, 'Calculation and abstraction', null, 2),
  ('2cbb5cc4-bbef-41e9-bf2c-3ce0ffd228a1', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5c8e2c69-9301-4ff3-ae0b-a4910adc9293', 'concept'::public.curated_course_node_type, 'Freedom, dependence, and impersonality', null, 3),
  ('be4eb59c-5f30-4e14-9a33-096dd5d57f2b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '14beafe7-6380-4b69-9708-46377d4e4b58', 'subtopic'::public.curated_course_node_type, 'The Metropolis and the Stranger', 'Students learn how urban life produces distinctive forms of perception, identity, and social distance.', 2),
  ('001715ae-7d11-477e-a8f5-a9f1b6f460a5', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'be4eb59c-5f30-4e14-9a33-096dd5d57f2b', 'concept'::public.curated_course_node_type, 'Blase attitude', null, 0),
  ('a1e47a78-6d60-47a5-913a-c3c051466de9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'be4eb59c-5f30-4e14-9a33-096dd5d57f2b', 'concept'::public.curated_course_node_type, 'Nervous stimulation', null, 1),
  ('6c120b82-0da2-4341-a450-3e1d40ad51eb', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'be4eb59c-5f30-4e14-9a33-096dd5d57f2b', 'concept'::public.curated_course_node_type, 'The stranger as near and far', null, 2),
  ('c582f6d1-6e03-4166-8b25-d47fb46843b4', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'be4eb59c-5f30-4e14-9a33-096dd5d57f2b', 'concept'::public.curated_course_node_type, 'Individuality and modern culture', null, 3),
  ('577f8c42-a1fa-48ae-8d06-546e1faefb58', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'W.E.B. Du Bois: The Color Line, Double Consciousness, and Racialized Modernity', 'Du Bois belongs at the center of classical theory. Students learn how race, empire, capitalism, knowledge, and democracy are inseparable in his account of modern society.', 7),
  ('5453d26d-8fc7-4294-ab89-9c88795dc47f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '577f8c42-a1fa-48ae-8d06-546e1faefb58', 'subtopic'::public.curated_course_node_type, 'The Color Line and Racialized Modernity', 'Students learn Du Bois''s argument that the modern world is structured by global racial hierarchy.', 0),
  ('92c9f37e-4e6d-4229-b2c1-b785b209a620', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5453d26d-8fc7-4294-ab89-9c88795dc47f', 'concept'::public.curated_course_node_type, 'The problem of the color line', null, 0),
  ('22e3278e-d585-43c0-9bea-9c86229dae8a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5453d26d-8fc7-4294-ab89-9c88795dc47f', 'concept'::public.curated_course_node_type, 'Race, labor, and capitalism', null, 1),
  ('f856d725-5b6c-451f-8a36-c295ffeae2c7', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5453d26d-8fc7-4294-ab89-9c88795dc47f', 'concept'::public.curated_course_node_type, 'Empire and colonial domination', null, 2),
  ('985aa7bf-1f47-41e9-823f-2a305c06bf63', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '5453d26d-8fc7-4294-ab89-9c88795dc47f', 'concept'::public.curated_course_node_type, 'Reconstruction and democracy', null, 3),
  ('401e6d8e-e588-414a-ba12-6f51f193dc19', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '577f8c42-a1fa-48ae-8d06-546e1faefb58', 'subtopic'::public.curated_course_node_type, 'Double Consciousness and the Veil', 'The gist is understanding subjectivity under racial domination as a social and historical condition.', 1),
  ('41083178-06c5-4055-871e-309461931b3b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '401e6d8e-e588-414a-ba12-6f51f193dc19', 'concept'::public.curated_course_node_type, 'The veil', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e4508bc8-3341-4c10-84ba-40253a65f8b9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '401e6d8e-e588-414a-ba12-6f51f193dc19', 'concept'::public.curated_course_node_type, 'Two-ness and self-consciousness', null, 1),
  ('4f895e1a-3d56-47e1-a2c9-ef234e4e7e1a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '401e6d8e-e588-414a-ba12-6f51f193dc19', 'concept'::public.curated_course_node_type, 'Recognition and misrecognition', null, 2),
  ('40f2e118-9e69-44f1-9bd3-e5701b11e89f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '401e6d8e-e588-414a-ba12-6f51f193dc19', 'concept'::public.curated_course_node_type, 'Identity, domination, and agency', null, 3),
  ('58dcbb52-a9ee-46f0-9db1-8e8cac19832a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '577f8c42-a1fa-48ae-8d06-546e1faefb58', 'subtopic'::public.curated_course_node_type, 'Empirical Sociology and Public Scholarship', 'Students learn Du Bois as a rigorous empirical researcher and public intellectual.', 2),
  ('5d9333a7-aee7-4087-885d-40b4d71b558f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '58dcbb52-a9ee-46f0-9db1-8e8cac19832a', 'concept'::public.curated_course_node_type, 'The Philadelphia Negro', null, 0),
  ('8ad01074-0fb3-4585-a405-f493c0db5d99', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '58dcbb52-a9ee-46f0-9db1-8e8cac19832a', 'concept'::public.curated_course_node_type, 'Atlanta School sociology', null, 1),
  ('ada6f659-514e-4be6-874b-f649a6dcf6f3', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '58dcbb52-a9ee-46f0-9db1-8e8cac19832a', 'concept'::public.curated_course_node_type, 'Data visualization and community study', null, 2),
  ('7dc342db-4b13-47ca-b304-e5af1e8ca496', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '58dcbb52-a9ee-46f0-9db1-8e8cac19832a', 'concept'::public.curated_course_node_type, 'Scholarship, activism, and public sociology', null, 3),
  ('2f12cf7d-bc32-4e9f-b89b-8b3d0365f127', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Harriet Martineau and Charlotte Perkins Gilman: Gender, Political Economy, and Reform', 'This unit widens the classical canon. Martineau and Gilman show that early sociology included rigorous method, translation, gender analysis, political economy, and reformist critique.', 8),
  ('f2916a8e-da64-48c6-8aad-f52c50ab00c9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2f12cf7d-bc32-4e9f-b89b-8b3d0365f127', 'subtopic'::public.curated_course_node_type, 'Harriet Martineau and Observational Method', 'Students learn Martineau''s contributions to comparative observation, morals and manners, democracy, and social reform.', 0),
  ('8888818d-6abd-422e-ab41-91c567147a42', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f2916a8e-da64-48c6-8aad-f52c50ab00c9', 'concept'::public.curated_course_node_type, 'Society in America', null, 0),
  ('6ea74586-4d18-4d25-8ec7-e70f4263bb87', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f2916a8e-da64-48c6-8aad-f52c50ab00c9', 'concept'::public.curated_course_node_type, 'Morals and manners', null, 1),
  ('f0f2ead4-f15f-4102-9b48-662b2407ffcc', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f2916a8e-da64-48c6-8aad-f52c50ab00c9', 'concept'::public.curated_course_node_type, 'Comparative observation', null, 2),
  ('d706d630-ccea-4fd6-8ff2-02e618b6c916', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f2916a8e-da64-48c6-8aad-f52c50ab00c9', 'concept'::public.curated_course_node_type, 'Abolition, democracy, and reform', null, 3),
  ('38c6f129-cafe-4ad3-bdd8-189b60d99624', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2f12cf7d-bc32-4e9f-b89b-8b3d0365f127', 'subtopic'::public.curated_course_node_type, 'Charlotte Perkins Gilman and Gendered Political Economy', 'The point is to analyze family, labor, dependency, and gender as social institutions rather than private arrangements.', 1),
  ('6c7cbb81-5acb-4b57-864d-c15e0c3e7545', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '38c6f129-cafe-4ad3-bdd8-189b60d99624', 'concept'::public.curated_course_node_type, 'Women and Economics', null, 0),
  ('e142d002-e247-4b9c-921d-9d98c3f1e53c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '38c6f129-cafe-4ad3-bdd8-189b60d99624', 'concept'::public.curated_course_node_type, 'Domestic labor and dependency', null, 1),
  ('47740a80-c987-4e17-91d2-9c8a14207057', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '38c6f129-cafe-4ad3-bdd8-189b60d99624', 'concept'::public.curated_course_node_type, 'Gender socialization', null, 2),
  ('eab1a533-640f-41a6-be80-eab7919ddb6a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '38c6f129-cafe-4ad3-bdd8-189b60d99624', 'concept'::public.curated_course_node_type, 'Reform, utopia, and institutional change', null, 3),
  ('abec580b-7d38-4e44-8443-bd1b98c0ac68', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2f12cf7d-bc32-4e9f-b89b-8b3d0365f127', 'subtopic'::public.curated_course_node_type, 'Feminist Recovery of Classical Theory', 'Students learn how recovering excluded thinkers changes the questions theory asks.', 2),
  ('d6c490c3-c10c-4599-ae08-7e3c03c0b2ed', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'abec580b-7d38-4e44-8443-bd1b98c0ac68', 'concept'::public.curated_course_node_type, 'Canon critique', null, 0),
  ('a3dd6ff3-d422-41d5-baf7-9cef7b48f68a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'abec580b-7d38-4e44-8443-bd1b98c0ac68', 'concept'::public.curated_course_node_type, 'Gender and knowledge production', null, 1),
  ('9b617f87-5baf-45ce-b958-0b9fcbfef2fe', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'abec580b-7d38-4e44-8443-bd1b98c0ac68', 'concept'::public.curated_course_node_type, 'Public writing and reform', null, 2),
  ('536dc248-17c6-4f61-90aa-5829bb33eb72', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'abec580b-7d38-4e44-8443-bd1b98c0ac68', 'concept'::public.curated_course_node_type, 'Intersection with race, class, and empire', null, 3),
  ('7b025a23-8976-4f03-9e57-27e3232789d0', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Religion, Morality, Secularization, and Collective Life', 'Religion is central to classical theory because it reveals how societies create meaning, authority, discipline, morality, solidarity, and conflict.', 9),
  ('8deec7af-7bfd-4019-9098-bf3fbf7d467d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '7b025a23-8976-4f03-9e57-27e3232789d0', 'subtopic'::public.curated_course_node_type, 'Durkheim on Ritual and Collective Life', 'Students learn religion as a social fact that produces moral community.', 0),
  ('628a9995-3b48-4281-b4c7-6dcc80b91e26', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8deec7af-7bfd-4019-9098-bf3fbf7d467d', 'concept'::public.curated_course_node_type, 'Sacred and profane', null, 0),
  ('9c399834-ca41-4d09-acd5-fee9ea1ff781', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8deec7af-7bfd-4019-9098-bf3fbf7d467d', 'concept'::public.curated_course_node_type, 'Totemism and classification', null, 1),
  ('74f5615c-9c8f-463e-a11d-05368b93413b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8deec7af-7bfd-4019-9098-bf3fbf7d467d', 'concept'::public.curated_course_node_type, 'Collective effervescence', null, 2),
  ('704207c9-ec78-4cbe-801a-fa668f87ee63', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8deec7af-7bfd-4019-9098-bf3fbf7d467d', 'concept'::public.curated_course_node_type, 'Ritual and solidarity', null, 3),
  ('32df2fbc-e645-4cfb-80d2-a95b03716908', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '7b025a23-8976-4f03-9e57-27e3232789d0', 'subtopic'::public.curated_course_node_type, 'Weber on Religion and Capitalism', 'The gist is understanding religion as an active force in economic and social organization.', 1),
  ('27c1b573-93d5-412d-a5aa-08e49e011637', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '32df2fbc-e645-4cfb-80d2-a95b03716908', 'concept'::public.curated_course_node_type, 'Ascetic Protestantism', null, 0),
  ('d50370c4-0fb1-4e5e-8bf9-a39ca1582eb6', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '32df2fbc-e645-4cfb-80d2-a95b03716908', 'concept'::public.curated_course_node_type, 'Calling and discipline', null, 1),
  ('53eef9a3-e190-4293-9d99-dcf4d5d78c16', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '32df2fbc-e645-4cfb-80d2-a95b03716908', 'concept'::public.curated_course_node_type, 'World religions and comparative sociology', null, 2),
  ('dc6ba601-5754-43da-aa0e-dc0e5e71bfbe', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '32df2fbc-e645-4cfb-80d2-a95b03716908', 'concept'::public.curated_course_node_type, 'Disenchantment and secularization', null, 3),
  ('883577f6-68c7-49cf-bb33-1a6652112e2b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '7b025a23-8976-4f03-9e57-27e3232789d0', 'subtopic'::public.curated_course_node_type, 'Marx and Critical Accounts of Religion', 'Students learn religion as consolation, ideology, protest, and social expression.', 2),
  ('561d62c2-4559-4120-9045-1b0add91b1f1', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '883577f6-68c7-49cf-bb33-1a6652112e2b', 'concept'::public.curated_course_node_type, 'Religion and alienation', null, 0),
  ('cbcaf08b-ebc9-48eb-80bd-c3938254f65c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '883577f6-68c7-49cf-bb33-1a6652112e2b', 'concept'::public.curated_course_node_type, 'Ideology and material conditions', null, 1),
  ('e91d0454-eca9-46fb-8fcf-59dbdb2e143f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '883577f6-68c7-49cf-bb33-1a6652112e2b', 'concept'::public.curated_course_node_type, 'Legitimation and critique', null, 2),
  ('bff36f1b-9a04-43c3-83cd-ba78d86014eb', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '883577f6-68c7-49cf-bb33-1a6652112e2b', 'concept'::public.curated_course_node_type, 'Secularization debates', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('7d02ffee-8cc3-4e36-b46b-1dd70bd66711', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Urbanization, Immigration, the Chicago School, and Early Empirical Sociology', 'Early empirical sociology turned theory toward cities, migration, neighborhoods, race relations, and everyday social worlds. Students connect classical concepts to field research.', 10),
  ('af254c93-dad2-4806-baa7-b2101086b815', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '7d02ffee-8cc3-4e36-b46b-1dd70bd66711', 'subtopic'::public.curated_course_node_type, 'Urbanization and Social Disorganization', 'Students learn how rapid urban growth produced new questions about community, deviance, inequality, and social order.', 0),
  ('a5d366fb-d734-4572-9477-f713b604d024', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af254c93-dad2-4806-baa7-b2101086b815', 'concept'::public.curated_course_node_type, 'Industrial city and migration', null, 0),
  ('e54bf39b-02bf-4161-bf61-b05dca34e239', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af254c93-dad2-4806-baa7-b2101086b815', 'concept'::public.curated_course_node_type, 'Neighborhood ecology', null, 1),
  ('85b5d770-3ebe-4d66-84a9-1275d447a7d0', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af254c93-dad2-4806-baa7-b2101086b815', 'concept'::public.curated_course_node_type, 'Social disorganization', null, 2),
  ('ce74236c-e1ba-4e89-a4a4-74cde32742b6', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af254c93-dad2-4806-baa7-b2101086b815', 'concept'::public.curated_course_node_type, 'Community, poverty, and institutions', null, 3),
  ('af238291-6474-43f5-91a8-4ff905cb4a1b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '7d02ffee-8cc3-4e36-b46b-1dd70bd66711', 'subtopic'::public.curated_course_node_type, 'The Chicago School', 'The point is to see how fieldwork, mapping, and urban observation became central to sociology.', 1),
  ('153c8de1-26ce-4aa3-a595-127172fcc5bc', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af238291-6474-43f5-91a8-4ff905cb4a1b', 'concept'::public.curated_course_node_type, 'Robert Park and Ernest Burgess', null, 0),
  ('fa5e7e85-aff6-4e69-a79b-bc9373c8a171', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af238291-6474-43f5-91a8-4ff905cb4a1b', 'concept'::public.curated_course_node_type, 'Urban ecology', null, 1),
  ('5f49853e-3409-40f6-8743-6ddadd149b29', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af238291-6474-43f5-91a8-4ff905cb4a1b', 'concept'::public.curated_course_node_type, 'Immigration and assimilation', null, 2),
  ('b07f6e67-84ed-4fa8-8496-5d874bc14156', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'af238291-6474-43f5-91a8-4ff905cb4a1b', 'concept'::public.curated_course_node_type, 'Case studies and ethnography', null, 3),
  ('328c29a8-eb43-4256-a25c-c34466aa2a4e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '7d02ffee-8cc3-4e36-b46b-1dd70bd66711', 'subtopic'::public.curated_course_node_type, 'Race, Migration, and Urban Modernity', 'Students learn to connect urban sociology to race, labor, segregation, and political power.', 2),
  ('d85786bc-63ae-4e6c-b651-c3d1d0a3fe63', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '328c29a8-eb43-4256-a25c-c34466aa2a4e', 'concept'::public.curated_course_node_type, 'The ghetto and segregation', null, 0),
  ('16742ad3-82cb-486c-99ae-8df8516dcdbe', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '328c29a8-eb43-4256-a25c-c34466aa2a4e', 'concept'::public.curated_course_node_type, 'Ethnic succession', null, 1),
  ('2ae51ba3-d6f6-454b-a1fd-8dc65eddda98', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '328c29a8-eb43-4256-a25c-c34466aa2a4e', 'concept'::public.curated_course_node_type, 'Policing and deviance', null, 2),
  ('4034a98a-6c2c-4c51-8b59-89111ba23a04', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '328c29a8-eb43-4256-a25c-c34466aa2a4e', 'concept'::public.curated_course_node_type, 'Du Bois and urban empirical sociology', null, 3),
  ('3890cb1b-5673-440d-bdb4-e0c437dbc46e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Method, Evidence, Ideal Types, and Comparative-Historical Analysis', 'Theory is also method. Students learn how classical theorists constructed concepts, selected evidence, compared cases, and made arguments about history and society.', 11),
  ('880e56b2-65bc-4365-806e-d2b368f059e8', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3890cb1b-5673-440d-bdb4-e0c437dbc46e', 'subtopic'::public.curated_course_node_type, 'Close Reading and Conceptual Reconstruction', 'Students learn to read difficult texts by identifying concepts, assumptions, claims, and tensions.', 0),
  ('b503d080-a707-4eb2-9e97-e25327040250', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '880e56b2-65bc-4365-806e-d2b368f059e8', 'concept'::public.curated_course_node_type, 'Thesis, concept, and evidence', null, 0),
  ('b834efb6-7b0e-45a7-90c3-ae7b0b1d6c3e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '880e56b2-65bc-4365-806e-d2b368f059e8', 'concept'::public.curated_course_node_type, 'Contextual reading', null, 1),
  ('6831bb8f-edd6-41ba-8894-97a22a833660', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '880e56b2-65bc-4365-806e-d2b368f059e8', 'concept'::public.curated_course_node_type, 'Key terms and definitions', null, 2),
  ('3daf7f26-eee6-4c6a-bda7-37883be201f5', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '880e56b2-65bc-4365-806e-d2b368f059e8', 'concept'::public.curated_course_node_type, 'Interpretive charity and critique', null, 3),
  ('83874517-813a-4ae2-b012-97c54e566498', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3890cb1b-5673-440d-bdb4-e0c437dbc46e', 'subtopic'::public.curated_course_node_type, 'Ideal Types and Comparative-Historical Method', 'The gist is learning how theory turns messy reality into analyzable models without confusing models for reality.', 1),
  ('488e1090-14f2-49d2-be84-04e4d679ec48', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83874517-813a-4ae2-b012-97c54e566498', 'concept'::public.curated_course_node_type, 'Weberian ideal types', null, 0),
  ('a3d949ca-e878-4d04-9526-4d4edd84ecd1', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83874517-813a-4ae2-b012-97c54e566498', 'concept'::public.curated_course_node_type, 'Comparative cases', null, 1),
  ('f2d3a02d-c7a5-480f-bacf-4ce7b0713f12', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83874517-813a-4ae2-b012-97c54e566498', 'concept'::public.curated_course_node_type, 'Historical sequences', null, 2),
  ('eb922531-1d5b-460d-944b-340acde68db4', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83874517-813a-4ae2-b012-97c54e566498', 'concept'::public.curated_course_node_type, 'Causal adequacy and interpretive adequacy', null, 3),
  ('4289c7ca-6d5f-403a-8560-70dd61688d18', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '3890cb1b-5673-440d-bdb4-e0c437dbc46e', 'subtopic'::public.curated_course_node_type, 'Evidence, Argument, and Writing Theory', 'Students learn to write theory papers that explain and evaluate concepts rather than merely summarize authors.', 2),
  ('cd84b733-ebcf-4ab4-8382-1a8d252f7764', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4289c7ca-6d5f-403a-8560-70dd61688d18', 'concept'::public.curated_course_node_type, 'Concept maps', null, 0),
  ('bee25c86-b334-4c03-ab37-534bf5724113', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4289c7ca-6d5f-403a-8560-70dd61688d18', 'concept'::public.curated_course_node_type, 'Comparative matrices', null, 1),
  ('7cf383ab-f405-442a-8595-eae80e42f46a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4289c7ca-6d5f-403a-8560-70dd61688d18', 'concept'::public.curated_course_node_type, 'Textual evidence', null, 2),
  ('30b145ba-8ac0-4d9c-8247-0c72ff65b32a', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4289c7ca-6d5f-403a-8560-70dd61688d18', 'concept'::public.curated_course_node_type, 'Application to empirical cases', null, 3),
  ('db49d705-4141-4267-86ce-45d71ea13c7f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Power and Inequality: Class, Status, Race, Gender, Empire, and Coloniality', 'Classical theory is indispensable for studying inequality, but it must be read critically. Students learn how class, status, race, gender, empire, and coloniality shape modern power.', 12),
  ('4b3ce1b4-b43f-4334-afcc-247fe4ec217d', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'db49d705-4141-4267-86ce-45d71ea13c7f', 'subtopic'::public.curated_course_node_type, 'Class, Status, and Power', 'Students compare Marx''s class analysis with Weber''s multidimensional account of stratification.', 0),
  ('0d513a43-9954-4eac-a34b-dc89b076b1c9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4b3ce1b4-b43f-4334-afcc-247fe4ec217d', 'concept'::public.curated_course_node_type, 'Class relations', null, 0),
  ('e00115ac-26dc-4578-9062-c31a02dc07c4', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4b3ce1b4-b43f-4334-afcc-247fe4ec217d', 'concept'::public.curated_course_node_type, 'Status honor', null, 1),
  ('5219cac8-c5d6-4e92-9606-7aa690c627ae', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4b3ce1b4-b43f-4334-afcc-247fe4ec217d', 'concept'::public.curated_course_node_type, 'Party and power', null, 2),
  ('1bf9ea00-cd8e-40af-be04-aa3828a471e4', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '4b3ce1b4-b43f-4334-afcc-247fe4ec217d', 'concept'::public.curated_course_node_type, 'Elites and domination', null, 3),
  ('254d70aa-0000-44fc-b12d-357852009f11', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'db49d705-4141-4267-86ce-45d71ea13c7f', 'subtopic'::public.curated_course_node_type, 'Race, Gender, and Social Reproduction', 'The point is to examine exclusions and recover theorists who analyzed domination beyond class alone.', 1),
  ('5f5ef73e-9d90-40be-bfb7-fe24f6fb3029', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '254d70aa-0000-44fc-b12d-357852009f11', 'concept'::public.curated_course_node_type, 'Du Bois and racial capitalism', null, 0);
