  ('87d6a758-506f-4425-b670-4904ab92b33f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '2232de97-021a-48d7-85a0-00842fa3b0b9', 'concept'::public.curated_course_node_type, 'Decolonial critique of the canon', null, 3),
  ('55a58ce3-ef79-4942-8895-0a4d3a61f1bd', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Comparing Classical Perspectives: Structure, Agency, Conflict, Order, and Meaning', 'This comparative unit helps students synthesize the course. They learn to use theory as a set of contrasting assumptions about human action, institutions, power, and social change.', 13),
  ('470a3222-a6f9-46b6-abc4-9cea51ce0374', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '55a58ce3-ef79-4942-8895-0a4d3a61f1bd', 'subtopic'::public.curated_course_node_type, 'Structure and Agency', 'Students compare how theorists explain the relation between individual action and social constraint.', 0),
  ('2b1f1a89-192b-440d-9a5d-0371e1e4d048', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '470a3222-a6f9-46b6-abc4-9cea51ce0374', 'concept'::public.curated_course_node_type, 'Marx and structural contradiction', null, 0),
  ('4247b937-5019-4794-a4a2-9373b1683f52', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '470a3222-a6f9-46b6-abc4-9cea51ce0374', 'concept'::public.curated_course_node_type, 'Durkheim and social facts', null, 1),
  ('eefe0a74-488a-4220-b2bf-10194ca3b05b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '470a3222-a6f9-46b6-abc4-9cea51ce0374', 'concept'::public.curated_course_node_type, 'Weber and meaningful action', null, 2),
  ('5c74e1ff-3f8e-42d8-9bec-01f62848e74e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '470a3222-a6f9-46b6-abc4-9cea51ce0374', 'concept'::public.curated_course_node_type, 'Simmel and interaction forms', null, 3),
  ('b27efa61-e748-4a36-8ecf-207806d43f8b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '55a58ce3-ef79-4942-8895-0a4d3a61f1bd', 'subtopic'::public.curated_course_node_type, 'Conflict and Order', 'The gist is to compare theories that emphasize domination, cohesion, meaning, or institutional coordination.', 1),
  ('9f9d5040-d3c2-4507-936e-0ab605d981be', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b27efa61-e748-4a36-8ecf-207806d43f8b', 'concept'::public.curated_course_node_type, 'Class conflict', null, 0),
  ('bbe91f14-ed92-4107-a17b-1155a800f21c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b27efa61-e748-4a36-8ecf-207806d43f8b', 'concept'::public.curated_course_node_type, 'Moral integration', null, 1),
  ('be50cba5-8fcd-4fe6-bf51-cd84cd4fc679', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b27efa61-e748-4a36-8ecf-207806d43f8b', 'concept'::public.curated_course_node_type, 'Legitimate domination', null, 2),
  ('1bde20cd-2b6e-44ce-95ef-e75afd4d4fb5', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'b27efa61-e748-4a36-8ecf-207806d43f8b', 'concept'::public.curated_course_node_type, 'Interactional tension and exchange', null, 3),
  ('f53f9dcf-4ee9-4e94-ad9f-0f31860ee76f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '55a58ce3-ef79-4942-8895-0a4d3a61f1bd', 'subtopic'::public.curated_course_node_type, 'Meaning and Material Conditions', 'Students learn to avoid false choices between culture and economy.', 2),
  ('e76718e5-2981-4e9d-8af8-ae8e3980bd08', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f53f9dcf-4ee9-4e94-ad9f-0f31860ee76f', 'concept'::public.curated_course_node_type, 'Ideology and material life', null, 0),
