  ('0907f6ed-c84d-4c06-ad11-119561c1245b', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f53f9dcf-4ee9-4e94-ad9f-0f31860ee76f', 'concept'::public.curated_course_node_type, 'Collective representations', null, 2),
  ('3086d13c-bb33-4e6e-9653-b0e1e7ff5503', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'f53f9dcf-4ee9-4e94-ad9f-0f31860ee76f', 'concept'::public.curated_course_node_type, 'Culture, money, race, and identity', null, 3),
  ('8eb51db3-8a2d-424a-84f8-27bc5294e819', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', null, 'topic'::public.curated_course_node_type, 'Classical Theory Today: Contemporary Relevance, Canon Critique, and Public Sociology', 'The final unit asks students to use classical theory now. Students apply concepts to contemporary problems while assessing what classical theory illuminates, distorts, or leaves out.', 14),
  ('e8c9f2d6-d7c5-4f4d-9135-2eabbf5aa17f', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8eb51db3-8a2d-424a-84f8-27bc5294e819', 'subtopic'::public.curated_course_node_type, 'Applying Classical Theory to Contemporary Problems', 'Students learn to use classical concepts in current analysis without forcing old frameworks onto new realities.', 0),
  ('ea80ccbe-00c2-43dd-a3a6-794974f02734', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e8c9f2d6-d7c5-4f4d-9135-2eabbf5aa17f', 'concept'::public.curated_course_node_type, 'Platform capitalism and alienation', null, 0),
