  ('ea783c04-9eee-45f7-9eef-eb588dccc632', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e8c9f2d6-d7c5-4f4d-9135-2eabbf5aa17f', 'concept'::public.curated_course_node_type, 'Anomie, polarization, and social isolation', null, 2),
  ('77521bbb-d63b-457e-a403-deafb6451e27', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', 'e8c9f2d6-d7c5-4f4d-9135-2eabbf5aa17f', 'concept'::public.curated_course_node_type, 'Race, inequality, and democracy', null, 3),
  ('83ff1d00-fb69-4b8b-b7e3-8c6e0344757e', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8eb51db3-8a2d-424a-84f8-27bc5294e819', 'subtopic'::public.curated_course_node_type, 'Critiquing the Canon', 'The point is to identify both enduring insight and historical limitation.', 1),
  ('ab2b9fd0-ee2c-4ced-bcf8-634ae9e41b22', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83ff1d00-fb69-4b8b-b7e3-8c6e0344757e', 'concept'::public.curated_course_node_type, 'Eurocentrism and colonial blind spots', null, 0),
  ('c9f7b9a0-83e4-4360-84e0-ef41a64c9f45', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83ff1d00-fb69-4b8b-b7e3-8c6e0344757e', 'concept'::public.curated_course_node_type, 'Gender exclusions', null, 1),
  ('5928ad04-424e-4bde-9a8d-dacbc693c31c', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '83ff1d00-fb69-4b8b-b7e3-8c6e0344757e', 'concept'::public.curated_course_node_type, 'Race and the marginalization of Du Bois', null, 2),
