  ('70a079b8-78a4-43fe-96e6-cb495f2642a9', 'b1c2d3e4-5f6a-4c91-8d01-2e3f4a5b6c11', '8eb51db3-8a2d-424a-84f8-27bc5294e819', 'subtopic'::public.curated_course_node_type, 'Public Sociology and Theory as Practice', 'Students learn that theory can inform research, policy, activism, journalism, and civic reasoning.', 2),
